def show(pos, r, skip=('belt','pole','pipe','group')):
    out=[]
    for e in get_entities(position=pos, radius=r):
        n=str(e.name)
        if any(s in n for s in skip): continue
        st=str(e.status).replace('EntityStatus.','')
        rec=''
        try:
            rc=e.recipe
            if rc: rec = rc if isinstance(rc,str) else (rc.name if hasattr(rc,'name') else rc.get('name'))
        except Exception: pass
        out.append(f"{n}@{e.position.x},{e.position.y}:{st}:{rec}")
    print(len(out)); print(' | '.join(out))
