def gridmap(cx, cy, r, x0, x1, y0, y1):
    g={}
    for e in get_entities(position=Position(x=cx,y=cy), radius=r):
        items=[]
        if hasattr(e,'belts'): items=[(b,'b') for b in e.belts]
        elif hasattr(e,'pipes'): items=[(p,'p') for p in e.pipes]
        elif hasattr(e,'poles'): items=[(p,'|') for p in e.poles]
        else:
            n=str(e.name); c='?'
            for k,v in (('assembling-machine-2','A'),('assembling-machine-1','a'),('long','L'),('inserter','i'),('furnace','F'),('turret','T'),('chest','c'),('lab','B'),('drill','D'),('splitter','S'),('chemical','C'),('refinery','R'),('tank','K'),('pumpjack','J')):
                if k in n: c=v; break
            items=[(e,c)]
        for it,c in items:
            p=it.position
            w=1;h=1
            try:
                w=int(it.tile_dimensions.tile_width); h=int(it.tile_dimensions.tile_height)
            except Exception: pass
            for dx in range(w):
                for dy in range(h):
                    tx=int(p.x-w/2+dx+0.5-0.5+0.5) if False else int((p.x - w/2 + dx + 0.5)//1)
                    ty=int((p.y - h/2 + dy + 0.5)//1)
                    g[(tx,ty)]=c
    for y in range(y0,y1+1):
        print(f"{y:4d} "+''.join(g.get((x,y),'.') for x in range(x0,x1+1)))
    print('     x0=',x0)
