    d={(1,0):Direction.RIGHT,(-1,0):Direction.LEFT,(0,1):Direction.DOWN,(0,-1):Direction.UP}[(dx,dy)]
    e=place_entity(Prototype.Inserter, d, pos)
    if not near(e.drop_position, drop):
        opp={Direction.RIGHT:Direction.LEFT,Direction.LEFT:Direction.RIGHT,Direction.UP:Direction.DOWN,Direction.DOWN:Direction.UP}[d]
        e=rotate_entity(e, opp)
    print('ins',px,py,'drop',e.drop_position,'pick',e.pickup_position)
    return e
